// grex reimplementation - pure std Rust

mod cli;
mod grapheme;
mod regex_gen;
mod output;
mod options;

use std::io::{self, Read, BufRead};
use std::process::ExitCode;

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().collect();
    match cli::parse_args(&args) {
        Ok(parsed) => run(parsed),
        Err(cli::CliError::Help) => {
            print!("{}", cli::short_help());
            ExitCode::SUCCESS
        }
        Err(cli::CliError::LongHelp) => {
            print!("{}", cli::long_help());
            ExitCode::SUCCESS
        }
        Err(cli::CliError::Version) => {
            println!("grex 1.4.6");
            ExitCode::SUCCESS
        }
        Err(cli::CliError::Msg(m)) => {
            eprint!("{}", m);
            ExitCode::from(2)
        }
    }
}

fn run(opts: options::Options) -> ExitCode {
    // Resolve inputs
    let mut test_cases: Vec<String> = Vec::new();

    if let Some(fname) = &opts.file {
        // Read from file, may have - for stdin
        let content = if fname == "-" {
            let mut s = String::new();
            match io::stdin().read_to_string(&mut s) {
                Ok(_) => s,
                Err(e) => {
                    eprintln!("error: {}", e);
                    return ExitCode::from(1);
                }
            }
        } else {
            match std::fs::read_to_string(fname) {
                Ok(s) => s,
                Err(e) => {
                    eprintln!("error: {}", e);
                    return ExitCode::from(1);
                }
            }
        };
        for line in content.split('\n') {
            let line = line.strip_suffix('\r').unwrap_or(line);
            test_cases.push(line.to_string());
        }
        // Remove final empty string only if it's from trailing newline
        if test_cases.last().map(|s| s.is_empty()).unwrap_or(false) {
            test_cases.pop();
        }
    } else {
        for inp in &opts.inputs {
            if inp == "-" {
                let stdin = io::stdin();
                let locked = stdin.lock();
                for line in locked.lines() {
                    match line {
                        Ok(l) => test_cases.push(l),
                        Err(e) => {
                            eprintln!("error: {}", e);
                            return ExitCode::from(1);
                        }
                    }
                }
            } else {
                test_cases.push(inp.clone());
            }
        }
    }

    // Filter out empty strings
    test_cases.retain(|s| !s.is_empty());

    if test_cases.is_empty() {
        let msg = format!(
            "thread 'main' ({}) panicked at /workspace/src/builder.rs:48:13:\nNo test cases have been provided for regular expression generation\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n",
            std::process::id()
        );
        eprintln!("{}", msg.trim_end());
        return ExitCode::from(101);
    }

    let regex = regex_gen::build(&test_cases, &opts);
    let formatted = output::format(&regex, &opts);
    println!("{}", formatted);

    ExitCode::SUCCESS
}
