use crate::options::Options;

pub enum CliError {
    Help,
    LongHelp,
    Version,
    Msg(String),
}

pub fn parse_args(args: &[String]) -> Result<Options, CliError> {
    let mut opts = Options::new();
    let mut i = 1;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "-h" => return Err(CliError::Help),
            "--help" => return Err(CliError::LongHelp),
            "-v" | "--version" => return Err(CliError::Version),
            "-d" | "--digits" => opts.digits = true,
            "-D" | "--non-digits" => opts.non_digits = true,
            "-s" | "--spaces" => opts.spaces = true,
            "-S" | "--non-spaces" => opts.non_spaces = true,
            "-w" | "--words" => opts.words = true,
            "-W" | "--non-words" => opts.non_words = true,
            "-e" | "--escape" => opts.escape = true,
            "--with-surrogates" => opts.with_surrogates = true,
            "-r" | "--repetitions" => opts.repetitions = true,
            "--no-start-anchor" => opts.no_start_anchor = true,
            "--no-end-anchor" => opts.no_end_anchor = true,
            "--no-anchors" => opts.no_anchors = true,
            "-x" | "--verbose" => opts.verbose = true,
            "-c" | "--colorize" => opts.colorize = true,
            "-i" | "--ignore-case" => opts.ignore_case = true,
            "-g" | "--capture-groups" => opts.capture_groups = true,
            "-f" | "--file" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::Msg(
                        "error: a value is required for '--file <FILE>' but none was supplied\n\nFor more information, try '--help'.\n".to_string(),
                    ));
                }
                opts.file = Some(args[i].clone());
            }
            "--min-repetitions" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::Msg(
                        "error: a value is required for '--min-repetitions <QUANTITY>' but none was supplied\n\nFor more information, try '--help'.\n".to_string(),
                    ));
                }
                match args[i].parse::<u32>() {
                    Ok(n) => opts.min_repetitions = n,
                    Err(_) => {
                        return Err(CliError::Msg(format!(
                            "error: invalid value '{}' for '--min-repetitions <QUANTITY>': invalid digit found in string\n\nFor more information, try '--help'.\n",
                            args[i]
                        )));
                    }
                }
            }
            "--min-substring-length" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::Msg(
                        "error: a value is required for '--min-substring-length <LENGTH>' but none was supplied\n\nFor more information, try '--help'.\n".to_string(),
                    ));
                }
                match args[i].parse::<u32>() {
                    Ok(n) => opts.min_substring_length = n,
                    Err(_) => {
                        return Err(CliError::Msg(format!(
                            "error: invalid value '{}' for '--min-substring-length <LENGTH>': invalid digit found in string\n\nFor more information, try '--help'.\n",
                            args[i]
                        )));
                    }
                }
            }
            // Handle short option clusters like -dsw
            _ => {
                if a.starts_with("--") {
                    return Err(CliError::Msg(format!(
                        "error: unexpected argument '{}' found\n\nUsage: grex [OPTIONS] {{INPUT...|--file <FILE>}}\n\nFor more information, try '--help'.\n",
                        a
                    )));
                } else if a.starts_with('-') && a.len() > 2 {
                    // Cluster of short flags
                    let chars: Vec<char> = a[1..].chars().collect();
                    for c in chars {
                        match c {
                            'd' => opts.digits = true,
                            'D' => opts.non_digits = true,
                            's' => opts.spaces = true,
                            'S' => opts.non_spaces = true,
                            'w' => opts.words = true,
                            'W' => opts.non_words = true,
                            'e' => opts.escape = true,
                            'r' => opts.repetitions = true,
                            'x' => opts.verbose = true,
                            'c' => opts.colorize = true,
                            'i' => opts.ignore_case = true,
                            'g' => opts.capture_groups = true,
                            'h' => return Err(CliError::Help),
                            'v' => return Err(CliError::Version),
                            _ => {
                                return Err(CliError::Msg(format!(
                                    "error: unexpected argument '-{}' found\n\nUsage: grex [OPTIONS] {{INPUT...|--file <FILE>}}\n\nFor more information, try '--help'.\n",
                                    c
                                )));
                            }
                        }
                    }
                } else {
                    // Regular input
                    opts.inputs.push(a.clone());
                }
            }
        }
        i += 1;
    }

    // Validation
    if opts.file.is_some() && !opts.inputs.is_empty() {
        return Err(CliError::Msg(
            "error: the argument '--file <FILE>' cannot be used with '[INPUT]...'\n\nUsage: grex --file <FILE> [INPUT]...\n\nFor more information, try '--help'.\n".to_string(),
        ));
    }
    if opts.file.is_none() && opts.inputs.is_empty() {
        return Err(CliError::Msg(
            "error: the following required arguments were not provided:\n  --file <FILE>\n  <INPUT>...\n\nUsage: grex [OPTIONS] {INPUT...|--file <FILE>}\n\nFor more information, try '--help'.\n".to_string(),
        ));
    }

    Ok(opts)
}

pub fn short_help() -> String {
    String::from(r#"grex 1.4.6
© 2019-today Peter M. Stahl <pemistahl@gmail.com>
Licensed under the Apache License, Version 2.0
Downloadable from https://crates.io/crates/grex
Source code at https://github.com/pemistahl/grex

grex generates regular expressions from user-provided test cases.

Usage: grex [OPTIONS] {INPUT...|--file <FILE>}

Input:
  [INPUT]...         One or more test cases separated by blank space
  -f, --file <FILE>  Reads test cases on separate lines from a file

Digit Options:
  -d, --digits      Converts any Unicode decimal digit to \d
  -D, --non-digits  Converts any character which is not a Unicode decimal digit to \D

Whitespace Options:
  -s, --spaces      Converts any Unicode whitespace character to \s
  -S, --non-spaces  Converts any character which is not a Unicode whitespace character to \S

Word Options:
  -w, --words      Converts any Unicode word character to \w
  -W, --non-words  Converts any character which is not a Unicode word character to \W

Escaping Options:
  -e, --escape           Replaces all non-ASCII characters with unicode escape sequences
      --with-surrogates  Converts astral code points to surrogate pairs if --escape is set

Repetition Options:
  -r, --repetitions                    Detects repeated non-overlapping substrings and converts them
                                       to {min,max} quantifier notation
      --min-repetitions <QUANTITY>     Specifies the minimum quantity of substring repetitions to be
                                       converted if --repetitions is set [default: 1]
      --min-substring-length <LENGTH>  Specifies the minimum length a repeated substring must have
                                       in order to be converted if --repetitions is set [default: 1]

Anchor Options:
      --no-start-anchor  Removes the caret anchor `^` from the resulting regular expression
      --no-end-anchor    Removes the dollar sign anchor `$` from the resulting regular expression
      --no-anchors       Removes the caret and dollar sign anchors from the resulting regular
                         expression

Display Options:
  -x, --verbose   Produces a nicer-looking regular expression in verbose mode
  -c, --colorize  Provides syntax highlighting for the resulting regular expression

Miscellaneous Options:
  -i, --ignore-case     Performs case-insensitive matching, letters match both upper and lower case
  -g, --capture-groups  Replaces non-capturing groups with capturing ones
  -h, --help            Prints help information
  -v, --version         Prints version information
"#)
}

pub fn long_help() -> String {
    String::from(r#"grex 1.4.6
© 2019-today Peter M. Stahl <pemistahl@gmail.com>
Licensed under the Apache License, Version 2.0
Downloadable from https://crates.io/crates/grex
Source code at https://github.com/pemistahl/grex

grex generates regular expressions from user-provided test cases.

Usage: grex [OPTIONS] {INPUT...|--file <FILE>}

Input:
  [INPUT]...
          One or more test cases separated by blank space

          Use a hyphen `-` to read test cases from standard input.

          Conflicts with --file.

  -f, --file <FILE>
          Reads test cases on separate lines from a file.

          Lines may be ended with either a newline `\n` or a carriage return with a line feed
          `\r\n`. The final line ending is optional.

          Use a hyphen `-` to read the filename from standard input.

          Conflicts with INPUT...

Digit Options:
  -d, --digits
          Converts any Unicode decimal digit to \d.

          Takes precedence over --words if both are set. Decimal digits are converted to \d,
          remaining word characters to \w.

          Takes precedence over --non-spaces if both are set. Decimal digits are converted to \d,
          remaining non-space characters to \S.

  -D, --non-digits
          Converts any character which is not a Unicode decimal digit to \D.

          Takes precedence over --non-words if both are set. Non-digits which are also non-word
          characters are converted to \D.

          Takes precedence over --non-spaces if both are set. Non-digits which are also non-space
          characters are converted to \D.

Whitespace Options:
  -s, --spaces
          Converts any Unicode whitespace character to \s.

          Takes precedence over --non-digits if both are set. Whitespace is converted to \s,
          remaining non-digits to \D.

          Takes precedence over --non-words if both are set. Whitespace is converted to \s,
          remaining non-word characters to \W.

  -S, --non-spaces
          Converts any character which is not a Unicode whitespace character to \S

Word Options:
  -w, --words
          Converts any Unicode word character to \w.

          Takes precedence over --non-digits if both are set. Word characters are converted to \w,
          remaining non-digits to \D.

          Takes precedence over --non-spaces if both are set. Word characters are converted to \w,
          remaining non-whitespace to \S.

  -W, --non-words
          Converts any character which is not a Unicode word character to \W.

          Takes precedence over --non-spaces if both are set. Non-word characters which are also
          non-whitespace are converted to \W.

Escaping Options:
  -e, --escape
          Replaces all non-ASCII characters with unicode escape sequences

      --with-surrogates
          Converts astral code points to surrogate pairs if --escape is set

Repetition Options:
  -r, --repetitions
          Detects repeated non-overlapping substrings and converts them to {min,max} quantifier
          notation

      --min-repetitions <QUANTITY>
          Specifies the minimum quantity of substring repetitions to be converted if --repetitions
          is set

          [default: 1]

      --min-substring-length <LENGTH>
          Specifies the minimum length a repeated substring must have in order to be converted if
          --repetitions is set

          [default: 1]

Anchor Options:
      --no-start-anchor
          Removes the caret anchor `^` from the resulting regular expression.

          By default, the caret anchor is added to every generated regular expression which
          guarantees that the expression matches the test cases given as input only at the start of
          a string.

          This flag removes the anchor, thereby allowing to match the test cases also when they do
          not occur at the start of a string.

