            "-D" | "--non-digits" => opts.non_digits = true,
            "-s" | "--spaces" => opts.spaces = true,
            "-S" | "--non-spaces" => opts.non_spaces = true,
            "-w" | "--words" => opts.words = true,
            "-W" | "--non-words" => opts.non_words = true,
            "-e" | "--escape" => opts.escape = true,
            "--with-surrogates" => opts.with_surrogates = true,
            "-r" | "--repetitions" => opts.repetitions = true,
            "--no-start-anchor" => opts.no_start_anchor = true,
            "--no-end-anchor" => opts.no_end_anchor = true,
            "--no-anchors" => opts.no_anchors = true,
            "-x" | "--verbose" => opts.verbose = true,
            "-c" | "--colorize" => opts.colorize = true,
            "-i" | "--ignore-case" => opts.ignore_case = true,
            "-g" | "--capture-groups" => opts.capture_groups = true,
            "-f" | "--file" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::Msg(
                        "error: a value is required for '--file <FILE>' but none was supplied\n\nFor more information, try '--help'.\n".to_string(),
                    ));
                }
                opts.file = Some(args[i].clone());
            }
            "--min-repetitions" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::Msg(
                        "error: a value is required for '--min-repetitions <QUANTITY>' but none was supplied\n\nFor more information, try '--help'.\n".to_string(),
                    ));
                }
                match args[i].parse::<u32>() {
                    Ok(n) => opts.min_repetitions = n,
                    Err(_) => {
                        return Err(CliError::Msg(format!(
                            "error: invalid value '{}' for '--min-repetitions <QUANTITY>': invalid digit found in string\n\nFor more information, try '--help'.\n",
                            args[i]
                        )));
                    }
                }
            }
            "--min-substring-length" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::Msg(
                        "error: a value is required for '--min-substring-length <LENGTH>' but none was supplied\n\nFor more information, try '--help'.\n".to_string(),
                    ));
                }
                match args[i].parse::<u32>() {
                    Ok(n) => opts.min_substring_length = n,
                    Err(_) => {
                        return Err(CliError::Msg(format!(
                            "error: invalid value '{}' for '--min-substring-length <LENGTH>': invalid digit found in string\n\nFor more information, try '--help'.\n",
                            args[i]
                        )));
                    }
                }
            }
            // Handle short option clusters like -dsw
            _ => {
                if a.starts_with("--") {
                    return Err(CliError::Msg(format!(
                        "error: unexpected argument '{}' found\n\nUsage: grex [OPTIONS] {{INPUT...|--file <FILE>}}\n\nFor more information, try '--help'.\n",
                        a
                    )));
                } else if a.starts_with('-') && a.len() > 2 {
                    // Cluster of short flags
                    let chars: Vec<char> = a[1..].chars().collect();
                    for c in chars {
                        match c {
                            'd' => opts.digits = true,
                            'D' => opts.non_digits = true,
                            's' => opts.spaces = true,
                            'S' => opts.non_spaces = true,
                            'w' => opts.words = true,
                            'W' => opts.non_words = true,
                            'e' => opts.escape = true,
                            'r' => opts.repetitions = true,
                            'x' => opts.verbose = true,
                            'c' => opts.colorize = true,
                            'i' => opts.ignore_case = true,
                            'g' => opts.capture_groups = true,
                            'h' => return Err(CliError::Help),
                            'v' => return Err(CliError::Version),
                            _ => {
                                return Err(CliError::Msg(format!(
                                    "error: unexpected argument '-{}' found\n\nUsage: grex [OPTIONS] {{INPUT...|--file <FILE>}}\n\nFor more information, try '--help'.\n",
                                    c
                                )));
                            }
                        }
                    }
                } else {
                    // Regular input
                    opts.inputs.push(a.clone());
                }
            }
        }
        i += 1;
    }

    // Validation
    if opts.file.is_some() && !opts.inputs.is_empty() {
        return Err(CliError::Msg(
            "error: the argument '--file <FILE>' cannot be used with '[INPUT]...'\n\nUsage: grex --file <FILE> [INPUT]...\n\nFor more information, try '--help'.\n".to_string(),
        ));
    }
    if opts.file.is_none() && opts.inputs.is_empty() {
        return Err(CliError::Msg(
            "error: the following required arguments were not provided:\n  --file <FILE>\n  <INPUT>...\n\nUsage: grex [OPTIONS] {INPUT...|--file <FILE>}\n\nFor more information, try '--help'.\n".to_string(),
        ));
    }

    Ok(opts)
}

