// Simplified grapheme handling - treat each unicode scalar value as a grapheme
// (This is incorrect for combining characters but works for most cases.)

pub fn to_graphemes(s: &str) -> Vec<String> {
    // Attempt grapheme-like clustering for combining marks
    let mut result: Vec<String> = Vec::new();
    for c in s.chars() {
        if is_combining(c) && !result.is_empty() {
            let last = result.last_mut().unwrap();
            last.push(c);
        } else {
            result.push(c.to_string());
        }
    }
    result
}

fn is_combining(c: char) -> bool {
    let cp = c as u32;
    // Combining Diacritical Marks: U+0300..U+036F
    // Combining Diacritical Marks Extended: U+1AB0..U+1AFF
    // Combining Diacritical Marks Supplement: U+1DC0..U+1DFF
    // Combining Half Marks: U+FE20..U+FE2F
    // Combining Diacritical Marks for Symbols: U+20D0..U+20FF
    matches!(cp,
        0x0300..=0x036F |
        0x1AB0..=0x1AFF |
        0x1DC0..=0x1DFF |
        0x20D0..=0x20FF |
        0xFE20..=0xFE2F
    )
}
