use crate::grapheme::to_graphemes;
use crate::options::Options;
use std::collections::BTreeMap;

/// Regex AST
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Regex {
    Empty,                   // matches empty
    Literal(Vec<String>),    // sequence of graphemes
    Concat(Vec<Regex>),
    Alt(Vec<Regex>),
    Optional(Box<Regex>),    // X?
    CharClass(Vec<String>),  // set of single-grapheme alternatives
    // Top-level anchors/wrappers handled in output stage
}

pub fn build(inputs: &[String], opts: &Options) -> Regex {
    // Deduplicate
    let mut seen = std::collections::BTreeSet::new();
    let mut deduped: Vec<Vec<String>> = Vec::new();
    for s in inputs {
        if !seen.contains(s) {
            seen.insert(s.clone());
            deduped.push(to_graphemes(s));
        }
    }

    // Apply character class conversion if requested
    let graphemes_list: Vec<Vec<String>> = deduped.iter().map(|gs| {
        gs.iter().map(|g| convert_grapheme(g, opts)).collect()
    }).collect();

    // Build regex from the list of grapheme sequences
    build_alt(&graphemes_list, opts)
}

fn convert_grapheme(g: &str, opts: &Options) -> String {
    // If grapheme is a single character, we may convert it to a class shorthand
    let chars: Vec<char> = g.chars().collect();
    if chars.len() != 1 {
        return g.to_string();
    }
    let c = chars[0];

    if opts.digits && is_digit(c) {
        return "\\d".to_string();
    }
    if opts.spaces && is_whitespace(c) {
        return "\\s".to_string();
    }
    if opts.words && is_word(c) {
        return "\\w".to_string();
    }
    if opts.non_digits && !is_digit(c) {
        return "\\D".to_string();
    }
    if opts.non_spaces && !is_whitespace(c) {
        return "\\S".to_string();
    }
    if opts.non_words && !is_word(c) {
        return "\\W".to_string();
    }
    g.to_string()
}

pub fn is_digit(c: char) -> bool {
