/// Build regex from list of grapheme sequences (each sequence = one test case)
fn build_alt(sequences: &[Vec<String>], opts: &Options) -> Regex {
    if sequences.is_empty() {
        return Regex::Empty;
    }
    if sequences.len() == 1 {
        if sequences[0].is_empty() {
            return Regex::Empty;
        }
        return Regex::Literal(sequences[0].clone());
    }
    combine(sequences, opts)
}

/// Combine multiple grapheme sequences via common prefix/suffix factoring and alternation
fn combine(sequences: &[Vec<String>], opts: &Options) -> Regex {
    // Find common prefix and suffix
    let pre_len = common_prefix_len(sequences);
    let suf_len_total = common_suffix_len(sequences, pre_len);

    if pre_len > 0 || suf_len_total > 0 {
        // Factor out prefix and suffix
        let pre: Vec<String> = sequences[0][..pre_len].to_vec();
        let seq_len = sequences[0].len();
        let suf: Vec<String> = sequences[0][seq_len - suf_len_total..].to_vec();

        let middles: Vec<Vec<String>> = sequences.iter().map(|s| {
            s[pre_len..s.len()-suf_len_total].to_vec()
        }).collect();

        let mid_regex = build_middle(&middles, opts);

        let mut parts: Vec<Regex> = Vec::new();
        if !pre.is_empty() {
            parts.push(Regex::Literal(pre));
        }
        if !is_empty_regex(&mid_regex) {
            parts.push(mid_regex);
        }
        if !suf.is_empty() {
            parts.push(Regex::Literal(suf));
        }

        if parts.is_empty() {
            return Regex::Empty;
        }
        if parts.len() == 1 {
            return parts.into_iter().next().unwrap();
        }
        return Regex::Concat(parts);
    }

    // No common prefix/suffix, alternate directly
    build_alt_no_factor(sequences, opts)
}

fn is_empty_regex(r: &Regex) -> bool {
    match r {
        Regex::Empty => true,
        Regex::Literal(l) => l.is_empty(),
        Regex::Concat(v) => v.is_empty(),
        _ => false,
    }
}

fn build_middle(middles: &[Vec<String>], opts: &Options) -> Regex {
    // Deduplicate
    let mut seen = std::collections::BTreeSet::new();
    let mut unique: Vec<Vec<String>> = Vec::new();
    for m in middles {
        let key = m.join("\x00");
        if !seen.contains(&key) {
            seen.insert(key);
            unique.push(m.clone());
        }
    }

    if unique.is_empty() {
        return Regex::Empty;
    }
    if unique.len() == 1 {
        let m = &unique[0];
        if m.is_empty() {
            return Regex::Empty;
        }
        return Regex::Literal(m.clone());
    }

    // Separate empty from non-empty
