fn combine(sequences: &[Vec<String>], opts: &Options) -> Regex {
    // Find common prefix and suffix
    let pre_len = common_prefix_len(sequences);
    let suf_len_total = common_suffix_len(sequences, pre_len);

    if pre_len > 0 || suf_len_total > 0 {
        // Factor out prefix and suffix
        let pre: Vec<String> = sequences[0][..pre_len].to_vec();
        let seq_len = sequences[0].len();
        let suf: Vec<String> = sequences[0][seq_len - suf_len_total..].to_vec();

        let middles: Vec<Vec<String>> = sequences.iter().map(|s| {
