    // Re-sort final_alt by length desc, alpha
    final_alt.sort_by(|a, b| {
        let la = regex_display_length(a);
        let lb = regex_display_length(b);
        lb.cmp(&la).then_with(|| regex_sort_key(a).cmp(&regex_sort_key(b)))
    });

