fn first_grapheme(r: &Regex) -> Option<String> {
    match r {
        Regex::Literal(l) => l.first().cloned(),
        Regex::Concat(v) => v.first().and_then(first_grapheme),
        Regex::Alt(v) => v.first().and_then(first_grapheme),
        Regex::Optional(inner) => first_grapheme(inner),
        _ => None,
    }
}

fn regex_display_length(r: &Regex) -> usize {
    // Approximate the rendered length of a regex, for sorting
    match r {
        Regex::Empty => 0,
        Regex::Literal(l) => l.iter().map(|g| g.chars().count()).sum(),
        Regex::Concat(v) => v.iter().map(regex_display_length).sum(),
        Regex::Alt(v) => v.iter().map(regex_display_length).sum::<usize>() + v.len().saturating_sub(1) + 4, // |'s plus (?:)
        Regex::Optional(inner) => regex_display_length(inner) + 1,
        Regex::CharClass(items) => items.iter().map(|g| g.chars().count()).sum::<usize>() + 2,
    }
}

fn regex_sort_key(r: &Regex) -> String {
    match r {
        Regex::Empty => String::new(),
        Regex::Literal(l) => l.concat(),
        Regex::Concat(v) => v.iter().map(regex_sort_key).collect::<Vec<_>>().concat(),
        Regex::Alt(v) => v.iter().map(regex_sort_key).collect::<Vec<_>>().concat(),
        Regex::Optional(inner) => regex_sort_key(inner),
        Regex::CharClass(items) => items.concat(),
    }
}

fn common_prefix_len(sequences: &[Vec<String>]) -> usize {
    if sequences.is_empty() {
        return 0;
    }
    let min_len = sequences.iter().map(|s| s.len()).min().unwrap();
    let mut i = 0;
    while i < min_len {
        let c = &sequences[0][i];
        if sequences.iter().any(|s| &s[i] != c) {
            break;
        }
        i += 1;
    }
    i
}

fn common_suffix_len(sequences: &[Vec<String>], pre_len: usize) -> usize {
    if sequences.is_empty() {
        return 0;
    }
    let min_remaining = sequences.iter().map(|s| s.len() - pre_len).min().unwrap();
    let mut i = 0;
    while i < min_remaining {
        let c = &sequences[0][sequences[0].len() - 1 - i];
        if sequences.iter().any(|s| &s[s.len() - 1 - i] != c) {
            break;
        }
        i += 1;
    }
    i
}
