# Add helper functions for regex-level common prefix/suffix factoring
addition = '''

/// Get the list of concat parts of a regex. For non-Concat, returns a single-element list.
fn to_parts(r: &Regex) -> Vec<Regex> {
    match r {
        Regex::Concat(v) => v.clone(),
        _ => vec![r.clone()],
    }
}

fn from_parts(parts: Vec<Regex>) -> Regex {
    if parts.is_empty() {
        return Regex::Empty;
    }
    if parts.len() == 1 {
        return parts.into_iter().next().unwrap();
    }
    Regex::Concat(parts)
}

/// If all alternatives have a common trailing regex part, factor it out.
/// Also try common leading part.
fn factor_common_regex_parts(alternatives: Vec<Regex>) -> Regex {
    if alternatives.len() < 2 {
        if alternatives.is_empty() {
            return Regex::Empty;
        }
        return alternatives.into_iter().next().unwrap();
    }

    let parts_per_alt: Vec<Vec<Regex>> = alternatives.iter().map(to_parts).collect();

    // Find common leading parts (must be identical regex structurally)
    let mut leading: Vec<Regex> = Vec::new();
    let mut i = 0;
    loop {
        let first = parts_per_alt[0].get(i).cloned();
        match first {
            None => break,
            Some(ref p) => {
                if parts_per_alt.iter().all(|parts| parts.get(i) == Some(p)) {
                    leading.push(p.clone());
                    i += 1;
                } else {
                    break;
                }
            }
        }
    }

    // Find common trailing parts
    let mut trailing: Vec<Regex> = Vec::new();
    let mut j = 0;
    loop {
        let min_remaining = parts_per_alt.iter().map(|p| p.len().saturating_sub(i)).min().unwrap_or(0);
        if j >= min_remaining {
            break;
        }
        let last0 = parts_per_alt[0][parts_per_alt[0].len() - 1 - j].clone();
        if parts_per_alt.iter().all(|parts| {
            parts[parts.len() - 1 - j] == last0
        }) {
            trailing.push(last0);
            j += 1;
        } else {
            break;
        }
    }
    trailing.reverse();

    if leading.is_empty() && trailing.is_empty() {
        return Regex::Alt(alternatives);
    }

    // Build middle alternatives
