// ==================== Repetition post-processing ====================

/// Apply repetition detection to the regex AST.
pub fn apply_repetitions(r: &Regex, opts: &Options) -> Regex {
    if !opts.repetitions {
        return r.clone();
    }
    let min_rep = opts.min_repetitions;
    let min_substr = opts.min_substring_length as usize;
    let min_reps_per_unit = (min_rep + 1) as usize;
    apply_rep_recursive(r, min_reps_per_unit, min_substr)
}

fn apply_rep_recursive(r: &Regex, min_reps: usize, min_substr: usize) -> Regex {
    match r {
        Regex::Literal(l) => compress_literal(l, min_reps, min_substr),
        Regex::Concat(parts) => {
            let new_parts: Vec<Regex> = parts.iter().map(|p| apply_rep_recursive(p, min_reps, min_substr)).collect();
            from_parts(new_parts)
        }
        Regex::Alt(alts) => {
            let new_alts: Vec<Regex> = alts.iter().map(|a| apply_rep_recursive(a, min_reps, min_substr)).collect();
            // After repetition processing, try to merge counts for same-unit repetitions
            merge_repetitions_in_alt(new_alts, min_reps, min_substr)
        }
        Regex::Optional(inner) => {
            let new_inner = apply_rep_recursive(inner, min_reps, min_substr);
            // Detect pattern: Optional(Repetition(u, min, max)) → Repetition(u, 0, max) but we encode as Optional
            Regex::Optional(Box::new(new_inner))
        }
        _ => r.clone(),
    }
}

/// Compress repetitions in a Literal sequence of graphemes.
fn compress_literal(graphemes: &[String], min_reps: usize, min_substr: usize) -> Regex {
    if graphemes.is_empty() {
        return Regex::Empty;
    }

    // Greedy: for each position, find best repetition starting here.
    let mut out: Vec<Regex> = Vec::new();
    let mut i = 0;
    while i < graphemes.len() {
        // Find best repetition starting at i
        let mut best_unit_len = 0usize;
        let mut best_count = 0usize;
        for unit_len in (min_substr..=(graphemes.len() - i) / min_reps).rev() {
            if unit_len == 0 {
                break;
            }
            // Check how many times this unit repeats starting at i
            let unit = &graphemes[i..i + unit_len];
            let mut count = 1;
            let mut j = i + unit_len;
            while j + unit_len <= graphemes.len() && &graphemes[j..j + unit_len] == unit {
                count += 1;
                j += unit_len;
            }
            if count >= min_reps {
                // Pick the largest-count option, preferring longer units
                if count * unit_len > best_count * best_unit_len {
                    best_unit_len = unit_len;
                    best_count = count;
                }
            }
        }

        if best_count >= min_reps && best_unit_len >= min_substr {
            let unit: Vec<String> = graphemes[i..i + best_unit_len].to_vec();
            out.push(Regex::Repetition(unit, best_count as u32, best_count as u32));
            i += best_unit_len * best_count;
        } else {
            out.push(Regex::Literal(vec![graphemes[i].clone()]));
            i += 1;
        }
    }

    from_parts(out)
}

fn merge_repetitions_in_alt(alts: Vec<Regex>, _min_reps: usize, _min_substr: usize) -> Regex {
    // If all alternatives are Repetition with the same unit, merge their counts into a range.
    if alts.len() < 2 {
        if alts.len() == 1 {
            return alts.into_iter().next().unwrap();
        }
        return Regex::Empty;
    }

    let first_unit: Option<Vec<String>> = match &alts[0] {
        Regex::Repetition(u, _, _) => Some(u.clone()),
        _ => None,
    };

    if let Some(unit) = first_unit {
        let all_same_unit = alts.iter().all(|a| matches!(a, Regex::Repetition(u, _, _) if u == &unit));
        if all_same_unit {
            let mut counts: Vec<u32> = Vec::new();
            for a in &alts {
                if let Regex::Repetition(_, min, max) = a {
                    for c in *min..=*max {
                        counts.push(c);
                    }
                }
            }
            counts.sort();
            counts.dedup();

            // Group into ranges
            let mut ranges: Vec<(u32, u32)> = Vec::new();
            for c in counts {
                if let Some(last) = ranges.last_mut() {
                    if c == last.1 + 1 {
                        last.1 = c;
                        continue;
                    }
                }
                ranges.push((c, c));
            }

            if ranges.len() == 1 {
                let (min, max) = ranges[0];
                return Regex::Repetition(unit, min, max);
            }
            let range_alts: Vec<Regex> = ranges.into_iter()
                .map(|(min, max)| Regex::Repetition(unit.clone(), min, max))
                .collect();
            return Regex::Alt(range_alts);
        }
    }

    Regex::Alt(alts)
}
