            if min == 0 {
                if max == 1 {
                    return Regex::Optional(Box::new(Regex::Literal(unit)));
                }
                return Regex::Optional(Box::new(Regex::Repetition(unit, 1, max)));
            } else if min == max {
                if min == 1 {
                    return Regex::Literal(unit);
                }
                return Regex::Repetition(unit, min, max);
            } else {
                return Regex::Repetition(unit, min, max);
            }
        }
    }

