/// Detects a cascade pattern and returns (unit, min_count, max_count) if detected.
fn detect_cascade(r: &Regex) -> Option<(Vec<String>, u32, u32)> {
    match r {
        Regex::Literal(l) if !l.is_empty() => Some((l.clone(), 1, 1)),
        Regex::Optional(inner) => {
            let (unit, _, max) = detect_cascade(inner)?;
            Some((unit, 0, max))
