                }
                return Regex::Optional(Box::new(Regex::Repetition(unit, 1, max)));
            } else if min == max {
                if min == 1 {
                    return Regex::Literal(unit);
                }
                return Regex::Repetition(unit, min, max);
            } else {
                return Regex::Repetition(unit, min, max);
            }
        }
    }

    match r {
        Regex::Literal(l) => compress_literal(l, min_reps, min_substr),
        Regex::Concat(parts) => {
            let new_parts: Vec<Regex> = parts.iter().map(|p| apply_rep_recursive(p, min_reps, min_substr)).collect();
            from_parts(new_parts)
        }
        Regex::Alt(alts) => {
            let new_alts: Vec<Regex> = alts.iter().map(|a| apply_rep_recursive(a, min_reps, min_substr)).collect();
            merge_repetitions_in_alt(new_alts, min_reps, min_substr)
        }
        Regex::Optional(inner) => {
            let new_inner = apply_rep_recursive(inner, min_reps, min_substr);
            Regex::Optional(Box::new(new_inner))
        }
        _ => r.clone(),
    }
}

/// Detects a cascade pattern and returns (unit, min_count, max_count) if detected.
fn detect_cascade(r: &Regex) -> Option<(Vec<String>, u32, u32)> {
    match r {
        Regex::Literal(l) if !l.is_empty() => Some((l.clone(), 1, 1)),
        Regex::Optional(inner) => {
            let (unit, _, max) = detect_cascade(inner)?;
            Some((unit, 0, max))
        }
        Regex::Concat(parts) => {
            // Concat = [Literal(unit), Optional(cascade_of_unit)] or similar
            if parts.len() < 2 {
                return None;
            }
            // Try interpreting: first part + rest.
            // The first part can be Literal(unit); rest should be cascade of same unit.
            if let Regex::Literal(l) = &parts[0] {
                let rest = if parts.len() == 2 {
                    parts[1].clone()
                } else {
                    Regex::Concat(parts[1..].to_vec())
                };
                let (u2, min2, max2) = detect_cascade(&rest)?;
                if &u2 == l {
                    return Some((u2, min2 + 1, max2 + 1));
                }
            }
            None
        }
        Regex::Repetition(u, min, max) => Some((u.clone(), *min, *max)),
        _ => None,
    }
}"""

