new = """/// Compress repetitions in a Literal sequence of graphemes.
/// Use dynamic programming to find the compression that minimizes total cost.
fn compress_literal(graphemes: &[String], min_reps: usize, min_substr: usize) -> Regex {
    if graphemes.is_empty() {
        return Regex::Empty;
    }
    let n = graphemes.len();

    // Find all possible repetitions: (start, unit_len, count)
    // A repetition is valid if count >= min_reps and unit_len >= min_substr.
    // We prefer repetitions with larger coverage (count * unit_len).

    // For each position, find the best starting repetition that maximizes total compression.
    // cost[i] = minimum number of "chars" needed to represent graphemes[i..].
    // We just need a placement of repetitions - use DP selecting best sequence.

    // For simplicity, use greedy with look-ahead: at each position, try all possible
    // repetitions starting here (including skipping to find later ones) and pick
    // the one with maximum total coverage.

    // Actually, simpler heuristic: find ALL non-overlapping repetitions prioritized by size.

    // Collect all candidate repetitions.
    let mut candidates: Vec<(usize, usize, usize)> = Vec::new(); // (start, unit_len, count)
    for start in 0..n {
        for unit_len in min_substr.max(1)..=(n - start) / min_reps {
            let unit = &graphemes[start..start + unit_len];
            let mut count = 1;
            let mut j = start + unit_len;
            while j + unit_len <= n && &graphemes[j..j + unit_len] == unit {
                count += 1;
                j += unit_len;
            }
            if count >= min_reps {
                candidates.push((start, unit_len, count));
            }
        }
    }

    // Sort candidates by: coverage desc, unit_len asc (prefer shorter units on tie)
    candidates.sort_by(|a, b| {
        let cov_a = a.1 * a.2;
        let cov_b = b.1 * b.2;
        cov_b.cmp(&cov_a).then_with(|| a.1.cmp(&b.1))
    });

    // Greedily select non-overlapping candidates.
    let mut taken: Vec<bool> = vec![false; n];
    let mut chosen: Vec<(usize, usize, usize)> = Vec::new();
    for &(start, ul, cnt) in &candidates {
        let total = ul * cnt;
        let end = start + total;
        if (start..end).any(|i| taken[i]) {
            continue;
        }
        for i in start..end {
            taken[i] = true;
        }
        chosen.push((start, ul, cnt));
    }
    chosen.sort_by_key(|&(s, _, _)| s);

    let mut out: Vec<Regex> = Vec::new();
    let mut i = 0;
    let mut ci = 0;
    while i < n {
        if ci < chosen.len() && chosen[ci].0 == i {
            let (start, ul, cnt) = chosen[ci];
            let unit: Vec<String> = graphemes[start..start + ul].to_vec();
            out.push(Regex::Repetition(unit, cnt as u32, cnt as u32));
            i = start + ul * cnt;
            ci += 1;
        } else {
            out.push(Regex::Literal(vec![graphemes[i].clone()]));
            i += 1;
        }
    }

    from_parts(out)
}"""

