    candidates.sort_by(|a, b| {
        let cov_a = a.1 * a.2;
        let cov_b = b.1 * b.2;
        cov_b.cmp(&cov_a).then_with(|| a.1.cmp(&b.1))
    });

    // Greedily select non-overlapping candidates.
    let mut taken: Vec<bool> = vec![false; n];
    let mut chosen: Vec<(usize, usize, usize)> = Vec::new();
    for &(start, ul, cnt) in &candidates {
        let total = ul * cnt;
        let end = start + total;
        if (start..end).any(|i| taken[i]) {
