        }
        for i in start..end {
            taken[i] = true;
        }
        chosen.push((start, ul, cnt));
    }
    chosen.sort_by_key(|&(s, _, _)| s);

    let mut out: Vec<Regex> = Vec::new();
    let mut i = 0;
    let mut ci = 0;
    while i < n {
        if ci < chosen.len() && chosen[ci].0 == i {
            let (start, ul, cnt) = chosen[ci];
            let unit: Vec<String> = graphemes[start..start + ul].to_vec();
            out.push(Regex::Repetition(unit, cnt as u32, cnt as u32));
            i = start + ul * cnt;
            ci += 1;
        } else {
            out.push(Regex::Literal(vec![graphemes[i].clone()]));
            i += 1;
        }
    }

